
import { useState } from 'react';
import { Link } from 'react-router-dom';

interface OrderSummaryProps {
  subtotal: number;
  itemCount: number;
}

export default function OrderSummary({ subtotal, itemCount }: OrderSummaryProps) {
  const [couponCode, setCouponCode] = useState('');
  const [couponApplied, setCouponApplied] = useState(false);
  const [couponError, setCouponError] = useState('');

  const shippingFee = subtotal >= 5500 ? 0 : 880;
  const tax = Math.floor((subtotal + shippingFee) * 0.1);
  const discount = couponApplied ? Math.floor(subtotal * 0.05) : 0;
  const total = subtotal + shippingFee + tax - discount;
  const earnPoints = Math.floor(total * 0.01);

  const handleCouponApply = () => {
    if (!couponCode.trim()) {
      setCouponError('クーポンコードを入力してください');
      return;
    }
    if (couponCode.toUpperCase() === 'WELCOME5') {
      setCouponApplied(true);
      setCouponError('');
    } else {
      setCouponError('無効なクーポンコードです');
      setCouponApplied(false);
    }
  };

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-6 sticky top-6">
      <h3 className="text-lg font-bold text-gray-800 mb-4">ご注文内容</h3>
      <div className="border-t border-gray-100 pt-4 space-y-3">
        <div className="flex justify-between text-sm">
          <span className="text-gray-500">商品小計（{itemCount}点）</span>
          <span className="text-gray-800 font-medium">¥{subtotal.toLocaleString()}</span>
        </div>
        <div className="flex justify-between text-sm">
          <span className="text-gray-500">送料</span>
          {shippingFee === 0 ? (
            <span className="text-emerald-600 font-medium">送料無料</span>
          ) : (
            <span className="text-gray-800 font-medium">¥{shippingFee.toLocaleString()}</span>
          )}
        </div>
        {shippingFee > 0 && (
          <p className="text-xs text-orange-500">
            あと¥{(5500 - subtotal).toLocaleString()}で送料無料！
          </p>
        )}
        <div className="flex justify-between text-sm">
          <span className="text-gray-500">消費税（10%）</span>
          <span className="text-gray-800 font-medium">¥{tax.toLocaleString()}</span>
        </div>
        {couponApplied && (
          <div className="flex justify-between text-sm">
            <span className="text-emerald-600">クーポン割引（5%OFF）</span>
            <span className="text-emerald-600 font-medium">-¥{discount.toLocaleString()}</span>
          </div>
        )}
      </div>

      {/* クーポン */}
      <div className="border-t border-gray-100 mt-4 pt-4">
        <p className="text-xs text-gray-500 mb-2">クーポンコード</p>
        <div className="flex gap-2">
          <input
            type="text"
            value={couponCode}
            onChange={(e) => {
              setCouponCode(e.target.value);
              setCouponError('');
            }}
            placeholder="コードを入力"
            className="flex-1 border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:border-red-500 cursor-text"
          />
          <button
            onClick={handleCouponApply}
            className="bg-gray-800 text-white px-4 py-2 rounded-md text-sm font-bold hover:bg-gray-700 whitespace-nowrap cursor-pointer"
          >
            適用
          </button>
        </div>
        {couponError && (
          <p className="text-xs text-red-500 mt-1">{couponError}</p>
        )}
        {couponApplied && (
          <p className="text-xs text-emerald-600 mt-1">クーポンが適用されました！</p>
        )}
      </div>

      {/* 合計 */}
      <div className="border-t border-dashed border-gray-300 mt-4 pt-4">
        <div className="flex justify-between items-end mb-1">
          <span className="text-base font-bold text-gray-800">合計金額（税込）</span>
          <span className="text-2xl font-bold text-red-600">¥{total.toLocaleString()}</span>
        </div>
        <p className="text-xs text-orange-500 text-right">
          <i className="ri-coin-line mr-1"></i>
          {earnPoints.toLocaleString()}ポイント獲得予定
        </p>
      </div>

      {/* アクションボタン */}
      <div className="mt-6 space-y-3">
        <button className="w-full bg-red-600 text-white py-3.5 rounded-lg font-bold text-base hover:bg-red-700 cursor-pointer whitespace-nowrap transition-colors flex items-center justify-center gap-2">
          レジに進む
          <i className="ri-arrow-right-line"></i>
        </button>
        <Link
          to="/shop"
          className="block w-full text-center text-sm text-gray-500 hover:text-red-600 cursor-pointer transition-colors py-2"
        >
          お買い物を続ける
        </Link>
      </div>

      {/* 安心情報 */}
      <div className="border-t border-gray-100 mt-5 pt-5 space-y-3">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 flex items-center justify-center bg-emerald-50 rounded-full flex-shrink-0">
            <i className="ri-shield-check-line text-emerald-600 text-sm"></i>
          </div>
          <p className="text-xs text-gray-500">安全なSSL暗号化通信で決済</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 flex items-center justify-center bg-emerald-50 rounded-full flex-shrink-0">
            <i className="ri-truck-line text-emerald-600 text-sm"></i>
          </div>
          <p className="text-xs text-gray-500">¥5,500以上のご注文で送料無料</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 flex items-center justify-center bg-emerald-50 rounded-full flex-shrink-0">
            <i className="ri-refresh-line text-emerald-600 text-sm"></i>
          </div>
          <p className="text-xs text-gray-500">未開封品は30日間返品・交換可能</p>
        </div>
      </div>
    </div>
  );
}
