
import { useState } from 'react';
import { Link } from 'react-router-dom';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';
import CartItem from './components/CartItem';
import OrderSummary from './components/OrderSummary';
import RecommendedProducts from './components/RecommendedProducts';
import { cartItems as initialCartItems } from '../../mocks/cart';

export default function CartPage() {
  const [items, setItems] = useState(initialCartItems);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');

  const showNotification = (message: string) => {
    setToastMessage(message);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 2500);
  };

  const handleQuantityChange = (id: number, quantity: number) => {
    setItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, quantity } : item))
    );
  };

  const handleRemove = (id: number) => {
    const removedItem = items.find((item) => item.id === id);
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (removedItem) {
      showNotification(`「${removedItem.name}」をカートから削除しました`);
    }
  };

  const handleAddRecommended = (product: { id: number; brand: string; name: string; price: number; image: string }) => {
    const existing = items.find((item) => item.id === product.id);
    if (existing) {
      handleQuantityChange(product.id, existing.quantity + 1);
      showNotification(`「${product.name}」の数量を増やしました`);
    } else {
      setItems((prev) => [
        ...prev,
        {
          id: product.id,
          brand: product.brand,
          name: product.name,
          partNumber: '-',
          compatibility: '-',
          price: product.price,
          quantity: 1,
          image: product.image,
          stock: 10,
          stockStatus: 'inStock',
          tags: [],
        },
      ]);
      showNotification(`「${product.name}」をカートに追加しました`);
    }
  };

  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="min-h-screen bg-gray-50">
      <GlobalHeader />
      <Breadcrumb items={[{ label: 'カート' }]} />

      <main className="max-w-[1400px] mx-auto px-6 pb-12">
        <h1 className="text-2xl font-bold text-gray-800 mb-1 flex items-center gap-2">
          <i className="ri-shopping-cart-2-line text-red-600 w-7 h-7 flex items-center justify-center"></i>
          ショッピングカート
        </h1>
        <p className="text-sm text-gray-400 mb-6">{totalQuantity}点の商品が入っています</p>

        {items.length === 0 ? (
          /* カートが空の場合 */
          <div className="bg-white border border-gray-200 rounded-lg p-16 text-center">
            <i className="ri-shopping-cart-line text-6xl text-gray-300 mb-4 block"></i>
            <h2 className="text-xl font-bold text-gray-600 mb-2">カートに商品がありません</h2>
            <p className="text-sm text-gray-400 mb-6">お気に入りの商品を見つけてカートに追加しましょう</p>
            <div className="flex gap-3 justify-center">
              <Link
                to="/shop"
                className="bg-red-600 text-white px-8 py-3 rounded-lg font-bold hover:bg-red-700 cursor-pointer whitespace-nowrap transition-colors"
              >
                ショッピングへ
              </Link>
              <Link
                to="/used-parts"
                className="bg-white text-gray-700 border border-gray-300 px-8 py-3 rounded-lg font-bold hover:bg-gray-50 cursor-pointer whitespace-nowrap transition-colors"
              >
                中古パーツを探す
              </Link>
            </div>
          </div>
        ) : (
          /* カートに商品がある場合 */
          <div className="flex gap-6">
            {/* 左カラム：商品リスト */}
            <div className="flex-1 min-w-0">
              <div className="space-y-4">
                {items.map((item) => (
                  <CartItem
                    key={item.id}
                    item={item}
                    onQuantityChange={handleQuantityChange}
                    onRemove={handleRemove}
                  />
                ))}
              </div>

              {/* おすすめ商品 */}
              <RecommendedProducts onAddToCart={handleAddRecommended} />
            </div>

            {/* 右カラム：注文サマリー */}
            <div className="w-80 flex-shrink-0">
              <OrderSummary subtotal={subtotal} itemCount={totalQuantity} />
            </div>
          </div>
        )}
      </main>

      {/* トースト通知 */}
      {showToast && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-gray-800 text-white px-6 py-3 rounded-lg shadow-lg text-sm font-medium z-50 animate-fade-in flex items-center gap-2">
          <i className="ri-check-line text-emerald-400"></i>
          {toastMessage}
        </div>
      )}

      <GlobalFooter />
    </div>
  );
}
