
import { Link } from 'react-router-dom';

interface CartItemData {
  id: number;
  brand: string;
  name: string;
  partNumber: string;
  compatibility: string;
  price: number;
  originalPrice?: number;
  quantity: number;
  image: string;
  stock: number;
  stockStatus: string;
  tags: string[];
}

interface CartItemProps {
  item: CartItemData;
  onQuantityChange: (id: number, quantity: number) => void;
  onRemove: (id: number) => void;
}

export default function CartItem({ item, onQuantityChange, onRemove }: CartItemProps) {
  const subtotal = item.price * item.quantity;

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-5 hover:shadow-md transition-shadow">
      <div className="flex gap-5">
        {/* 商品画像 */}
        <Link to={`/product/${item.id}`} className="flex-shrink-0 cursor-pointer">
          <div className="w-28 h-28 bg-gray-50 rounded-lg overflow-hidden border border-gray-100">
            <img
              src={item.image}
              alt={item.name}
              className="w-full h-full object-cover object-top"
            />
          </div>
        </Link>

        {/* 商品情報 */}
        <div className="flex-1 min-w-0">
          <div className="flex gap-1.5 mb-1.5 flex-wrap">
            {item.tags.map((tag, idx) => (
              <span
                key={idx}
                className={`text-xs px-2 py-0.5 rounded whitespace-nowrap ${
                  tag === '送料無料' ? 'bg-emerald-500 text-white' :
                  tag === 'SALE' ? 'bg-orange-500 text-white' :
                  'bg-gray-400 text-white'
                }`}
              >
                {tag}
              </span>
            ))}
            {item.stockStatus === 'inStock' && (
              <span className="text-xs px-2 py-0.5 rounded bg-green-100 text-green-700 whitespace-nowrap">
                在庫あり
              </span>
            )}
          </div>
          <p className="text-xs text-gray-400 mb-0.5">{item.brand}</p>
          <Link to={`/product/${item.id}`} className="cursor-pointer hover:text-red-600 transition-colors">
            <h3 className="text-sm font-bold text-gray-800 mb-1 line-clamp-2">{item.name}</h3>
          </Link>
          <p className="text-xs text-gray-400">品番：{item.partNumber}</p>
          <p className="text-xs text-gray-400">適合：{item.compatibility}</p>
        </div>

        {/* 価格・数量 */}
        <div className="flex-shrink-0 w-52 flex flex-col items-end justify-between">
          <div className="text-right">
            {item.originalPrice && (
              <p className="text-xs text-gray-400 line-through">
                ¥{item.originalPrice.toLocaleString()}
              </p>
            )}
            <p className="text-sm text-gray-600">
              単価 <span className="font-bold text-gray-800">¥{item.price.toLocaleString()}</span>
            </p>
          </div>

          {/* 数量調整 */}
          <div className="flex items-center gap-0 border border-gray-300 rounded-md overflow-hidden">
            <button
              onClick={() => onQuantityChange(item.id, Math.max(1, item.quantity - 1))}
              className="w-9 h-9 flex items-center justify-center bg-gray-50 hover:bg-gray-100 cursor-pointer transition-colors text-gray-600"
              disabled={item.quantity <= 1}
            >
              <i className="ri-subtract-line text-sm"></i>
            </button>
            <span className="w-12 h-9 flex items-center justify-center text-sm font-bold text-gray-800 bg-white border-x border-gray-300">
              {item.quantity}
            </span>
            <button
              onClick={() => onQuantityChange(item.id, Math.min(item.stock, item.quantity + 1))}
              className="w-9 h-9 flex items-center justify-center bg-gray-50 hover:bg-gray-100 cursor-pointer transition-colors text-gray-600"
              disabled={item.quantity >= item.stock}
            >
              <i className="ri-add-line text-sm"></i>
            </button>
          </div>

          <div className="flex items-center gap-4">
            <button
              onClick={() => onRemove(item.id)}
              className="text-xs text-gray-400 hover:text-red-500 cursor-pointer transition-colors flex items-center gap-1"
            >
              <i className="ri-delete-bin-line text-sm"></i>
              削除
            </button>
            <p className="text-lg font-bold text-red-600">
              ¥{subtotal.toLocaleString()}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
